-- Corrige request_correction: el alias «x» chocaba con la variable «x» y toda solicitud fallaba.
CREATE OR REPLACE FUNCTION public.request_correction(_uid uuid,_motivo text,_propuesta jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE x jsonb; rid uuid; BEGIN IF NOT public.is_active(auth.uid()) OR (_uid<>auth.uid() AND NOT public.is_manager()) OR NOT public.is_active(_uid) THEN RAISE EXCEPTION 'Sin permiso'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(_uid::text,0)); IF length(trim(_motivo))<1 OR jsonb_typeof(_propuesta)<>'array' OR jsonb_array_length(_propuesta) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Motivo y propuesta obligatorios'; END IF; FOR x IN SELECT value FROM jsonb_array_elements(_propuesta) LOOP IF x->>'original_id' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM fichajes WHERE id=(x->>'original_id')::uuid AND user_id=_uid) THEN RAISE EXCEPTION 'Original no pertenece al trabajador'; END IF; IF coalesce((x->>'anular')::boolean,false) AND x->>'original_id' IS NULL THEN RAISE EXCEPTION 'Anulación sin original'; END IF; IF NOT coalesce((x->>'anular')::boolean,false) AND (x->>'tipo' IS NULL OR x->>'tipo' NOT IN ('entrada','pausa','reanudar','salida') OR x->>'at' IS NULL OR (x->>'at')::timestamptz>now()) THEN RAISE EXCEPTION 'Hora o tipo inválidos'; END IF; END LOOP; IF EXISTS(SELECT 1 FROM jsonb_array_elements(_propuesta) el WHERE el.value->>'original_id' IS NOT NULL GROUP BY el.value->>'original_id' HAVING count(*)>1) THEN RAISE EXCEPTION 'Original repetido'; END IF; INSERT INTO solicitudes_correccion(user_id,solicitada_por,motivo,propuesta) VALUES(_uid,auth.uid(),trim(_motivo),_propuesta) RETURNING id INTO rid; RETURN rid; END $$;
